-- Execute once in Neon SQL editor
CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY,username VARCHAR(24) NOT NULL UNIQUE,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,bio TEXT NOT NULL DEFAULT '',avatar_url TEXT NOT NULL DEFAULT '',email_verified BOOLEAN NOT NULL DEFAULT FALSE,is_verified BOOLEAN NOT NULL DEFAULT FALSE,is_admin BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS users_email_lower ON users (LOWER(email));
CREATE UNIQUE INDEX IF NOT EXISTS users_username_lower ON users (LOWER(username));
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS email_tokens (token_hash TEXT PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS artists (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL UNIQUE,description TEXT NOT NULL DEFAULT '',image_url TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS albums (id BIGSERIAL PRIMARY KEY,artist_id BIGINT NOT NULL REFERENCES artists(id),title TEXT NOT NULL,cover_url TEXT NOT NULL DEFAULT '',release_date TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS tracks (id BIGSERIAL PRIMARY KEY,album_id BIGINT NOT NULL REFERENCES albums(id) ON DELETE CASCADE,title TEXT NOT NULL,track_number INT NOT NULL DEFAULT 1,duration_seconds INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS ratings (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,album_id BIGINT NOT NULL REFERENCES albums(id) ON DELETE CASCADE,rating NUMERIC(3,1) NOT NULL CHECK(rating BETWEEN 0 AND 10),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,album_id));
CREATE TABLE IF NOT EXISTS reviews (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,album_id BIGINT NOT NULL REFERENCES albums(id) ON DELETE CASCADE,rating NUMERIC(3,1) NOT NULL CHECK(rating BETWEEN 0 AND 10),title TEXT NOT NULL,body TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS comments (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,review_id BIGINT NOT NULL REFERENCES reviews(id) ON DELETE CASCADE,parent_id BIGINT REFERENCES comments(id),body TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS ratings_album_idx ON ratings(album_id);
CREATE INDEX IF NOT EXISTS reviews_album_idx ON reviews(album_id);
